import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import FranchiseList from './FranchiseList';

const Dashboard = () => {
  const navigate = useNavigate();
  const [activeButton, setActiveButton] = useState(''); // State to track the active button
  const [sidebarOpen, setSidebarOpen] = useState(false); // State to control sidebar visibility

  const handleNavigation = (path, buttonName) => {
    setActiveButton(buttonName); // Set the active button
    navigate(path); // Navigate to the corresponding path
    setSidebarOpen(false); // Close the sidebar after navigation
  };

  const toggleSidebar = () => {
    setSidebarOpen(!sidebarOpen); // Toggle the sidebar visibility
  };

  return (
    <div style={styles.container}>
      <h1>Superadmin Dashboard</h1>

      {/* Hamburger Menu Icon */}
      <div style={styles.hamburgerContainer} onClick={toggleSidebar}>
        <div style={styles.hamburgerIcon}></div>
        <div style={styles.hamburgerIcon}></div>
        <div style={styles.hamburgerIcon}></div>
      </div>

      {/* Sidebar */}
      {sidebarOpen && (
        <div style={styles.sidebar}>
          <button
            onClick={() => handleNavigation('/create-user', 'Create User')}
            style={activeButton === 'Create User' ? styles.activeButton : styles.button}
          >
            Create User
          </button>
          <button
            onClick={() => handleNavigation('/create-franchise', 'Franchise')}
            style={activeButton === 'Franchise' ? styles.activeButton : styles.button}
          >
            Franchise
          </button>
          <button
            onClick={() => handleNavigation('/exam-data', 'Manage Exam Data')}
            style={activeButton === 'Manage Exam Data' ? styles.activeButton : styles.button}
          >
            Manage Exam Data
          </button>
        </div>
      )}

      {/* Franchise List */}
      <FranchiseList />
    </div>
  );
};

const styles = {
  container: {
    padding: '20px',
    textAlign: 'center',
  },
  hamburgerContainer: {
    display: 'flex',
    flexDirection: 'column',
    cursor: 'pointer',
    marginBottom: '20px',
  },
  hamburgerIcon: {
    width: '30px',
    height: '4px',
    backgroundColor: '#333',
    margin: '5px 0',
  },
  sidebar: {
    position: 'absolute',
    left: 0,
    top: 0,
    width: '200px',
    height: '100%',
    backgroundColor: '#333',
    color: 'white',
    padding: '20px',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'flex-start',
    zIndex: 1000,
  },
  buttonContainer: {
    display: 'flex',
    justifyContent: 'center',
    marginBottom: '20px',
  },
  button: {
    backgroundColor: '#007bff',
    color: 'white',
    border: 'none',
    padding: '10px 20px',
    margin: '0 10px',
    fontSize: '16px',
    cursor: 'pointer',
    borderRadius: '5px',
    transition: 'background-color 0.3s ease',
  },
  activeButton: {
    backgroundColor: '#28a745', // Green color for active button
    color: 'white',
    border: 'none',
    padding: '10px 20px',
    margin: '0 10px',
    fontSize: '16px',
    cursor: 'pointer',
    borderRadius: '5px',
    transition: 'background-color 0.3s ease',
  },
};

export default Dashboard;
